/* ---------- ch2 quarterly revenue ---------- */
(function(){const s=$('#qchart'); const data=[["25Q1",376],["25Q2",787],["25Q3",1382],["25Q4",2040],["26Q1",4731],["26Q2",11555],["26Q3",16942,true]];
 const L=64,R=704,T=32,B=352; let mode='lin'; const bw=(R-L)/data.length;
 const defs=el('defs',{},s); const pat=el('pattern',{id:'ghost',width:8,height:8,patternUnits:'userSpaceOnUse',patternTransform:'rotate(45)'},defs); el('rect',{width:2,height:8,fill:'rgba(168,122,0,.5)'},pat);
 const gGrid=el('g',{},s), gBars=el('g',{},s), gLab=el('g',{},s);
 el('line',{x1:L,x2:R,y1:B,y2:B,class:'ax'},s);
 const bars=data.map((d,i)=>{const x=L+i*bw+bw*.18, w=bw*.64;
  const r=el('rect',{x,y:B,width:w,height:0,rx:4,fill:d[2]?'url(#ghost)':(i===5?C.mark:C.s4),stroke:d[2]?C.mark:'none','stroke-dasharray':d[2]?'4 4':'','stroke-width':1,class:'grow'},gBars);
  const t=el('text',{x:x+w/2,y:B-8,'text-anchor':'middle',class:'lbl'},gLab,d[2]?'≈16,900':fmt(d[1]));
  el('text',{x:x+w/2,y:B+24,'text-anchor':'middle'},gLab,d[0]); return {r,t,v:d[1],x,w,ghost:!!d[2]}});
 const note=el('g',{},s); const nx=L+3*bw+bw*.18+bw*.64*.55; el('line',{x1:nx,x2:nx,y1:T+8,y2:B,stroke:C.dim,'stroke-dasharray':'2 4'},note);
 el('text',{x:nx-8,y:T+20,'text-anchor':'end',fill:C.fg2},note,'Opus 4.5 출시(2025.11)'); el('text',{x:nx-8,y:T+36,'text-anchor':'end',fill:C.fg2},note,'뒤 전 분기 대비 48% → 132%');
 /* tooltip story */
 const tip=el('g',{opacity:0},s); const tipBg=el('rect',{width:136,height:44,rx:8,fill:C.s3,stroke:C.s4},tip); const tip1=el('text',{x:12,y:18,class:'lbl'},tip,''); const tip2=el('text',{x:12,y:34,fill:C.mark},tip,'');
 function yv(v){ if(mode==='lin') return B-(v/18000)*(B-T); const lo=Math.log10(100),hi=Math.log10(20000); return B-((Math.log10(v)-lo)/(hi-lo))*(B-T);}
 function grid(){while(gGrid.firstChild)gGrid.removeChild(gGrid.firstChild); const ticks=mode==='lin'?[4000,8000,12000,16000]:[100,1000,10000];
  ticks.forEach(v=>{const y=yv(v); el('line',{x1:L,x2:R,y1:y,y2:y,class:'grid'},gGrid); el('text',{x:L-8,y:y+4,'text-anchor':'end'},gGrid,fmt(v))})}
 function layout(){bars.forEach(b=>{const y=yv(b.v); b.r.setAttribute('y',y); b.r.setAttribute('height',B-y); b.t.setAttribute('y',y-8)})}
 grid(); layout();
 const go=grow(bars.map(b=>b.r),{stagger:90}); const lab=fadeIn(bars.map(b=>b.t).concat([note]),{delay:700,stagger:70});
 once($('#qpanel'),()=>{go();lab()},0.3);
 $$('#qpanel .tog').forEach(t=>t.addEventListener('click',()=>{mode=t.dataset.scale; $$('#qpanel .tog').forEach(x=>x.setAttribute('aria-pressed',x===t?'true':'false')); grid(); layout(); showTip(cur)}));
 let cur=1, timer=0; const qoq=[null,109,76,48,132,144,null];
 function showTip(i){const b=bars[i]; if(!b) return; bars.forEach((x,j)=>{ if(!x.ghost) x.r.setAttribute('fill', j===i?C.mark:(j===5&&i===-1?C.mark:C.s4)) });
  tip1.textContent=data[i][0]+' · '+fmt(data[i][1])+'M$'; tip2.textContent=qoq[i]!=null?('전 분기 대비 +'+qoq[i]+'% (계산)'):'';
  let tx=Math.min(R-136,Math.max(L,b.x+b.w/2-68)); let ty=Math.max(4,yv(b.v)-64); tip.setAttribute('transform','translate('+tx+','+ty+')'); tip.style.transition='opacity .3s '+EASE; tip.setAttribute('opacity',1);}
 function loop(){ cur=cur%6+1; if(cur>5) cur=1; showTip(cur); }
 whileVisible($('#qchart'),()=>{ if(!timer){ setTimeout(()=>{showTip(cur)},1800); timer=setInterval(loop,1900);} },()=>{clearInterval(timer);timer=0;});
})();

/* ---------- ch3 waterfall ---------- */
(function(){const s=$('#wf'); const rows=[["영업손실",-693,"op"],["이자수익",1111,"gain"],["공정가치 변동",-72388,"fv"],["기타 영업외",-8757,"oth"],["법인세",-21,"op"],["순손실",-80748,"total"]];
 const L=168,R=592,T=24,rowH=52, x0=R, min=-82000; const xs=v=>x0+(v/(-min))*(R-L);
 const defs=el('defs',{},s); const pat=el('pattern',{id:'hatch',width:8,height:8,patternUnits:'userSpaceOnUse',patternTransform:'rotate(45)'},defs); el('rect',{width:3,height:8,fill:'rgba(214,58,38,.7)'},pat);
 el('line',{x1:x0,x2:x0,y1:T-8,y2:T+rowH*rows.length,class:'ax'},s); el('text',{x:x0,y:T-12,'text-anchor':'middle','font-size':10},s,'0');
 let cum=0; const items=rows.map((r,i)=>{const y=T+i*rowH; let a,b; if(r[2]==='total'){a=0;b=r[1]}else{a=cum;b=cum+r[1];cum=b}
  const xa=xs(Math.max(a,b)), xb=xs(Math.min(a,b)); const w=Math.max(3,xa-xb);
  const fill=r[2]==='gain'?C.gain:(r[2]==='fv'||r[2]==='oth')?'url(#hatch)':r[2]==='total'?C.loss:'#EE8A7C';
  const g=el('g',{},s); if(i>0&&r[2]!=='total') el('line',{x1:xs(a),x2:xs(a),y1:y-16,y2:y+8,stroke:C.faint,'stroke-dasharray':'2 4'},g);
  const rect=el('rect',{x:xb,y:y+8,width:w,height:rowH-24,rx:4,fill,stroke:(r[2]==='fv'||r[2]==='oth')?C.loss:'none',class:r[1]>0?'grow':'growx'},g);
  if(r[1]>0){rect.style.transformOrigin='0% 50%'}
  el('text',{x:0,y:y+rowH/2+4,class:'lbl'},g,r[0]);
  const vt=el('text',{x:R+16,y:y+rowH/2+4,fill:r[1]>0?C.gain:C.loss,class:'lbl'},g,(r[1]>0?'+':'')+fmt(r[1]));
  return {g,rect,vt,kind:r[2]}});
 const adj=el('text',{x:0,y:T+rowH*rows.length+24,fill:C.gain,class:'lbl',opacity:0},s,'빗금 두 줄을 걷어내면 +397(계산). 주식보상비용 등까지 되돌린 비GAAP 조정순이익은 +2,671');
 const go=grow(items.map(i=>i.rect),{axis:'x',stagger:160,dur:1100,ease:IO}); const lab=fadeIn(items.map(i=>i.vt),{delay:600,stagger:160});
 once($('#wf'),()=>{go();lab()},0.3);
 let hide=false; $('#wfToggle').addEventListener('click',e=>{hide=!hide;e.currentTarget.setAttribute('aria-pressed',hide);
  items.forEach(it=>{it.g.style.transition='opacity .5s '+EASE; it.g.style.opacity=(hide&&(it.kind==='fv'||it.kind==='oth'||it.kind==='total'))?'.12':'1'}); adj.style.transition='opacity .5s '+EASE; adj.setAttribute('opacity',hide?1:0)});
})();

/* ---------- ch3 quarterly operating income ---------- */
(function(){const s=$('#opq'); const d=[["25Q1",-935],["25Q2",-1200],["25Q3",-3089],["25Q4",-2836],["26Q1",-1667],["26Q2",974]];
 const L=56,R=704,T=24,B=272, max=1400,min=-3400; const y=v=>T+(max-v)/(max-min)*(B-T); const y0=y(0); const bw=(R-L)/d.length;
 [-3000,-2000,-1000,1000].forEach(v=>{el('line',{x1:L,x2:R,y1:y(v),y2:y(v),class:'grid'},s);el('text',{x:L-8,y:y(v)+4,'text-anchor':'end'},s,fmt(v))});
 el('line',{x1:L,x2:R,y1:y0,y2:y0,stroke:C.fg,'stroke-width':1},s); el('text',{x:L-8,y:y0+4,'text-anchor':'end',fill:C.fg},s,'0');
 const rs=[], ls=[]; d.forEach((q,i)=>{const x=L+i*bw+bw*.22,w=bw*.56; const top=q[1]>0?y(q[1]):y0, h=Math.abs(y(q[1])-y0);
  const r=el('rect',{x,y:top,width:w,height:h,rx:4,fill:q[1]>0?C.gain:(q[0]==='25Q3'?C.loss:'#E9A296'),class:'grow'},s); r.style.transformOrigin=q[1]>0?'50% 100%':'50% 0%'; rs.push(r);
  const t=el('text',{x:x+w/2,y:q[1]>0?y(q[1])-8:y(q[1])+20,'text-anchor':'middle',class:'lbl',fill:q[1]>0?C.gain:C.fg},s,(q[1]>0?'+':'')+fmt(q[1])); ls.push(t);
  el('text',{x:x+w/2,y:q[1]>0?y0+20:y0-8,'text-anchor':'middle'},s,q[0]);
  if(q[0]==='25Q3'){const b=el('text',{x:x+w/2,y:y(q[1])+36,'text-anchor':'middle','font-size':10,fill:C.mark},s,'Bartz 1,500 포함'); ls.push(b)}});
 const go=grow(rs,{stagger:110}); const lab=fadeIn(ls,{delay:700,stagger:90}); once($('#opq'),()=>{go();lab()},0.3);
})();

/* ---------- ch4 compute ratio ---------- */
(function(){const s=$('#cratio'); const d=[["25Q1",251],["25Q2",177],["25Q3",148],["25Q4",144],["26Q1",72],["26Q2",48]];
 const L=56,R=688,T=24,B=272,max=280; const y=v=>B-(v/max)*(B-T); const x=i=>L+i*(R-L)/(d.length-1);
 [50,150,200,250].forEach(v=>{el('line',{x1:L,x2:R,y1:y(v),y2:y(v),class:'grid'},s);el('text',{x:L-8,y:y(v)+4,'text-anchor':'end'},s,v+'%')});
 el('line',{x1:L,x2:R,y1:y(100),y2:y(100),stroke:C.mark,'stroke-dasharray':'6 6'},s); el('text',{x:R,y:y(100)-8,'text-anchor':'end',fill:C.mark},s,'100% · 비용과 매출이 같은 선');
 const pts=d.map((q,i)=>[x(i),y(q[1])]); const pathD='M'+pts.map(p=>p.join(',')).join(' L');
 const area=el('path',{d:pathD+' L'+x(d.length-1)+','+B+' L'+x(0)+','+B+' Z',fill:'rgba(0,0,0,.04)'},s);
 const line=el('path',{d:pathD,fill:'none',stroke:C.fg,'stroke-width':2.5,'stroke-linejoin':'round'},s);
 const dots=[], labs=[]; d.forEach((q,i)=>{dots.push(el('circle',{cx:x(i),cy:y(q[1]),r:5,fill:C.s1,stroke:C.fg,'stroke-width':2},s)); labs.push(el('text',{x:x(i),y:y(q[1])-16,'text-anchor':'middle',class:'lbl'},s,q[1]+'%')); el('text',{x:x(i),y:B+24,'text-anchor':'middle'},s,q[0])});
 const rider=el('circle',{r:7,fill:C.mark,opacity:0},s);
 const go=draw(line,{dur:1600}); const pd=popIn(dots,{delay:300,stagger:180}); const lb=fadeIn(labs.concat([area]),{delay:500,stagger:160});
 once($('#cratio'),()=>{go();pd();lb()},0.3);
 let rafId=0, t0=0, live=false; const len=()=>line.getTotalLength();
 function ride(t){ if(!live) return; if(!t0) t0=t; const k=((t-t0)%4200)/4200; const e=k<.5?4*k*k*k:1-Math.pow(-2*k+2,3)/2; const p=line.getPointAtLength(len()*e); rider.setAttribute('cx',p.x); rider.setAttribute('cy',p.y); rider.setAttribute('opacity', k>.94||k<.03?0:1); rafId=requestAnimationFrame(ride); }
 whileVisible(s,()=>{ if(!live){live=true; setTimeout(()=>{t0=0; rafId=requestAnimationFrame(ride)},1900)} },()=>{live=false;cancelAnimationFrame(rafId)});
})();

/* ---------- ch4 squares ---------- */
(function(){const box=$('#squares'); const items=[["브로드컴","1,612","5년 장비 리스 전체(TPU)",1612,""],["SpaceXAI","최대 1,205","2029년까지, NVIDIA GPU",1205,"max"],["구글","≈1,145","2026.4~2033.7",1145,""],["아마존","1,100","2026.5~2036.4",1100,""],["추가 TPU","1,250~1,500","2028~2031 인도 추정",1500,"est"],["Nscale","최대 446","2033년까지, NVIDIA GPU",446,"max"],["Lambda","≈413","2034년까지, NVIDIA GPU",413,""],["마이크로소프트","449","2026.11~2033.5",449,""]];
 let done=false;
 function render(){box.innerHTML=''; const ms=Math.min(224,box.clientWidth*0.46); items.forEach(it=>{const side=Math.sqrt(it[3]/1612)*ms; const d=document.createElement('div'); d.className='sq '+it[4]+(done||!anim?'':' pop'); d.style.width=side+'px'; d.style.height=side+'px'; d.innerHTML='<b>'+it[1]+'</b><span>'+it[0]+'<br>'+it[2]+'</span>'; box.appendChild(d)});
  const t=document.createElement('div'); t.className='sq total'+(done||!anim?'':' pop'); const ts=ms*.62; t.style.width=ts+'px'; t.style.height=ts+'px'; t.innerHTML='<b>$ ____</b><span>총액 칸은 비어 있습니다</span>'; box.appendChild(t);}
 render(); let rt; window.addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(render,150)});
 once(box,()=>{ $$('.sq',box).forEach((n,i)=>setTimeout(()=>n.classList.add('in'),150+i*80)); setTimeout(()=>{done=true},1200) },0.3);
})();

/* ---------- ch5 customers ---------- */
(function(){const s=$('#cust'); const d=[["2023.12",20,"≈20",0],["2024.12",200,"≈200",12],["2025.09",950,"950+",21],["2025.12",1500,"≈1,500",24],["2026.09",11900,"11,900+",33]];
 const L=64,R=688,T=32,B=256; const lo=1,hi=Math.log10(20000); const y=v=>B-((Math.log10(v)-lo)/(hi-lo))*(B-T); const x=m=>L+m/33*(R-L);
 [10,100,1000,10000].forEach(v=>{el('line',{x1:L,x2:R,y1:y(v),y2:y(v),class:'grid'},s);el('text',{x:L-8,y:y(v)+4,'text-anchor':'end'},s,fmt(v))});
 const line=el('path',{d:'M'+d.map(q=>x(q[3])+','+y(q[1])).join(' L'),fill:'none',stroke:C.gain,'stroke-width':2.5},s);
 const dots=[],labs=[]; d.forEach((q,i)=>{dots.push(el('circle',{cx:x(q[3]),cy:y(q[1]),r:i===4?8:5,fill:i===4?C.gain:C.s1,stroke:C.gain,'stroke-width':2},s)); labs.push(el('text',{x:x(q[3]),y:y(q[1])-16,'text-anchor':i===4?'end':'middle',class:'lbl'},s,q[2])); el('text',{x:x(q[3]),y:B+24,'text-anchor':'middle','font-size':10},s,q[0])});
 const go=draw(line,{dur:1500}); const pd=popIn(dots,{delay:300,stagger:220}); const lb=fadeIn(labs,{delay:500,stagger:220});
 once($('#cust'),()=>{go();pd();lb()},0.3);
})();
(function(){const rows=$$('#pyr div'); rows.forEach(r=>{if(anim){r.style.transform='scaleX(.6)';r.style.opacity='0'}});
 once($('#pyr'),()=>rows.forEach((r,i)=>{ if(!anim) return; r.style.transition='transform 900ms '+E+' '+(i*120)+'ms, opacity 600ms '+EASE+' '+(i*120)+'ms'; r.style.transform='none'; r.style.opacity='1'}),0.4)})();
(function(){const cs=$$('#coins .nine .c'); cs.forEach(c=>{if(anim){c.style.opacity='0';c.style.transform='scale(.86)'}});
 once($('#coins'),()=>cs.forEach((c,i)=>{ if(!anim) return; c.style.transition='opacity 500ms '+EASE+' '+(200+i*70)+'ms, transform 700ms '+E+' '+(200+i*70)+'ms'; c.style.opacity='1'; c.style.transform='none'; setTimeout(()=>{c.style.transition='';c.style.transform=''},1400+i*70)}),0.5);
 let k=0,tm=0; whileVisible($('#coins'),()=>{ if(!tm) tm=setInterval(()=>{cs.forEach((c,i)=>c.classList.toggle('lit',i===k)); k=(k+1)%(cs.length+3)},260) },()=>{clearInterval(tm);tm=0;cs.forEach(c=>c.classList.remove('lit'))});
})();

/* ---------- ch6 network ---------- */
(function(){const s=$('#net'); const cx=360,cy=224; const nodes=[["아마존",-90,["inv","cmp","dst","riv"]],["구글",-30,["inv","cmp","dst","riv"]],["마이크로소프트",30,["inv","cmp","dst","riv"]],["브로드컴",90,["inv","cmp"]],["AMD",150,["inv","cmp"]],["SpaceXAI",210,["cmp"]],["NVIDIA",250,["cmp"]]];
 const colors={inv:C.mark,cmp:C.fg,dst:C.gain,riv:C.loss}; const offs={inv:-9,cmp:-3,dst:3,riv:9};
 const notes={"아마존":"Class N 5%+","구글":"Class N 5%+","마이크로소프트":"449억 약정","브로드컴":"매입약정 미인출","AMD":"Class N 조건부 매입","SpaceXAI":"최대 1,205억","NVIDIA":"GPU"};
 const gE=el('g',{},s), gP=el('g',{},s), gN=el('g',{},s); const edges=[];
 nodes.forEach((n,ni)=>{const a=n[1]*Math.PI/180, r=170; const nx=cx+Math.cos(a)*r*1.55, ny=cy+Math.sin(a)*r;
  n[2].forEach((rel,ri)=>{const px=-Math.sin(a)*offs[rel], py=Math.cos(a)*offs[rel]; const dd=`M${cx+px},${cy+py} Q${(cx+nx)/2+px*2},${(cy+ny)/2+py*2} ${nx+px},${ny+py}`;
   const cond=rel==='inv'&&(n[0]==='브로드컴'||n[0]==='AMD'); const p=el('path',{d:dd,class:'edge',stroke:colors[rel],opacity:.55,'stroke-dasharray':cond?'4 5':''},gE); const pu=el('path',{d:dd,class:'pulse',stroke:colors[rel]},gP); if(cond) pu.style.display='none'; pu.style.animationDelay=(-(ni*0.37+ri*0.61))+'s'; edges.push({p,pu,rel})});
  const g0=el('g',{class:'node',transform:`translate(${nx},${ny})`},gN); const g=el('g',{class:'ni'},g0); el('circle',{r:34},g); el('text',{'text-anchor':'middle',y:0,'font-size':n[0].length>5?11:12},g,n[0]); el('text',{'text-anchor':'middle',y:16,class:'ty'},g,n[2].length+'개 역할'); el('text',{'text-anchor':'middle',y:52,class:'ty'},g,notes[n[0]]);
 });
 const c0=el('g',{class:'node',transform:`translate(${cx},${cy})`},gN); const c=el('g',{class:'ni'},c0); el('circle',{r:48,style:'fill:#F5DC5A;stroke:none'},c); el('text',{'text-anchor':'middle',y:5,style:'fill:#131209;font-weight:700','font-size':14},c,'Anthropic');
 const on={inv:1,cmp:1,dst:1,riv:1}; function upd(){edges.forEach(e=>{e.p.style.opacity=on[e.rel]?.55:.04; e.pu.style.opacity=on[e.rel]?1:0})} upd();
 $$('#netCtrls .tog').forEach(t=>t.addEventListener('click',()=>{on[t.dataset.rel]=!on[t.dataset.rel]; t.setAttribute('aria-pressed',on[t.dataset.rel]?'true':'false'); upd()}));
 const draws=edges.filter(e=>!e.p.getAttribute('stroke-dasharray')).map(e=>draw(e.p,{dur:1200,delay:200})); const pn=popIn($$('#net .ni'),{delay:200,stagger:70});
 once(s,()=>{draws.forEach(f=>f());pn()},0.3);
 whileVisible(s,()=>s.classList.add('live'),()=>s.classList.remove('live'));
 const RN={inv:'지분·자금',cmp:'컴퓨트 공급',dst:'고객·유통',riv:'경쟁'}; const ul=document.createElement('ul'); ul.className='netlist'; ul.innerHTML=nodes.map(n=>'<li><b>'+n[0]+'</b><span>'+n[2].map(r=>'<i>'+RN[r]+((r==='inv'&&(n[0]==='브로드컴'||n[0]==='AMD'))?'(조건부)':'')+'</i>').join('')+'</span><small style="font:400 12px/16px var(--fm);color:var(--dim)">'+notes[n[0]]+'</small></li>').join(''); s.after(ul);
})();

/* ---------- ch6 stair ---------- */
(function(){const s=$('#stair'); const d=[["C","2023",11.2261],["D","2024",30.0045],["E","2025 초",56.0865],["F","2025 하",140.9676],["G","2026 초",259.1364],["H","2026 중",589.0095]];
 const L=56,R=688,T=32,B=264,max=640; const y=v=>B-(v/max)*(B-T); const bw=(R-L)/d.length;
 [100,200,300,400,500,600].forEach(v=>{el('line',{x1:L,x2:R,y1:y(v),y2:y(v),class:'grid'},s);el('text',{x:L-8,y:y(v)+4,'text-anchor':'end'},s,v+'달러')});
 let path=`M${L},${B}`; d.forEach((q,i)=>{path+=` L${L+i*bw},${y(q[2])} L${L+(i+1)*bw},${y(q[2])}`});
 const line=el('path',{d:path,fill:'none',stroke:C.mark,'stroke-width':2.5},s);
 const labs=[]; d.forEach((q,i)=>{labs.push(el('text',{x:L+i*bw+bw/2,y:y(q[2])-12-((s.getBoundingClientRect().width<500&&i%2===0)?22:0),'text-anchor':'middle',class:'lbl'},s,q[2]+'달러')); el('text',{x:L+i*bw+bw/2,y:B+20,'text-anchor':'middle'},s,'시리즈 '+q[0]); el('text',{x:L+i*bw+bw/2,y:B+36,'text-anchor':'middle','font-size':10,fill:C.faint},s,q[1])});
 const go=draw(line,{dur:1800}); const lb=fadeIn(labs,{delay:400,stagger:260}); once(s,()=>{go();lb()},0.3);
})();

/* ---------- ch7 vote donut + slider ---------- */
